/** Every card definition, tagged with its pack and the image folder of that pack. */
export const DEFS = PACKS.flatMap(p => p.cards.map(d => ({ ...d, pack: p.id, dir: p.dir })))

/** Card id (OCTGN GUID for the core set) → card definition */
export const BY_ID = Object.fromEntries(DEFS.map(d => [d.id, d]))

